{
  "assessment": "The source reports a quantitative analysis of CDW peak width and correlation length as a function of temperature in LSCO, with a two-channel decomposition of the observed width into domain and phase contributions. The key quantitative relations are the decomposition equation and the correlation length conversion. The paper provides specific numeric values for FWHM at two temperatures, correlation length at Tc, and a BCS-like fit for phase coherence enhancement. However, the BCS-like fit parameters are not explicitly given in the text, and the decomposition equation is presented without numeric values for the domain and phase terms. The extraction focuses on the two-channel decomposition and the correlation length conversion, which are the most quantitative and reproducible relations. The case is authoring-ready because there is at least one numeric control (temperature), one numeric readout (FWHM or correlation length), and a quantitative mechanism (the decomposition equation).",
  "case_authoring_ready": true,
  "source": {
    "citation": "H. Lee, Superconductivity Reinforces Charge-Density-Wave Phase Coherence across Cuprates, Physical Review Letters (2026), DOI:10.1103/g41t-8456",
    "journal_doi": "10.1103/g41t-8456",
    "arxiv_versioned_id": "2605.11401v1"
  },
  "paper_scope": "The paper reports resonant soft x-ray scattering measurements of charge-density-wave (CDW) order in La1.885Sr0.115CuO4 (LSCO) and a disordered variant, showing that superconductivity enhances CDW phase coherence below Tc. It introduces a coherence-sensitive momentum-profile analysis that separates the observed CDW peak width into domain-size and phase-coherence contributions, and compares the temperature dependence of the CDW peak width across multiple cuprate families.",
  "mechanisms": [
    {
      "mechanism_id": "cdw_width_decomposition",
      "statement": "The observed CDW peak width squared is the sum of a temperature-independent domain-broadening term and a temperature-dependent phase-coherence term, where the phase term is the inverse of the phase coherence length.",
      "equations": [
        "Delta_q_obs^2(T) = Delta_q_dom^2 + Delta_q_phi^2(T)",
        "Delta_q_phi(T) = xi_phi^{-1}(T)"
      ],
      "variable_names": [
        "Delta_q_obs",
        "Delta_q_dom",
        "Delta_q_phi",
        "xi_phi"
      ],
      "parameters": [
        {
          "name": "delta_q_dom_squared",
          "value": 0.0,
          "uncertainty": "Not reported; the domain term is described as varying only weakly with temperature and is not numerically specified in the text.",
          "unit": "r.l.u.^2",
          "role": "Domain-broadening contribution to the squared observed width; treated as a constant in the decomposition.",
          "anchors": [
            {
              "line_start": 132,
              "line_end": 137,
              "support": "Equation (1) states Delta_q_obs^2 = Delta_q_dom^2 + Delta_q_phi^2, with Delta_q_dom described as disorder-dominated broadening that varies only weakly with temperature."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 129,
          "line_end": 137,
          "support": "The observed width separates into two independent contributions: Delta_q_obs^2 = Delta_q_dom^2 + Delta_q_phi^2, where Delta_q_phi = xi_phi^{-1}."
        }
      ]
    },
    {
      "mechanism_id": "correlation_length_conversion",
      "statement": "The real-space correlation length of CDW order is obtained from the measured FWHM of the momentum profile using xi = 2/FWHM.",
      "equations": [
        "xi = 2 / FWHM"
      ],
      "variable_names": [
        "xi",
        "FWHM"
      ],
      "parameters": [
        {
          "name": "fwhm_to_xi_factor",
          "value": 2.0,
          "uncertainty": "Not reported; the factor 2 is stated as the conversion relation.",
          "unit": "dimensionless",
          "role": "Conversion factor from FWHM (in r.l.u.) to correlation length (in Angstrom), assuming the relation xi = 2/FWHM.",
          "anchors": [
            {
              "line_start": 113,
              "line_end": 113,
              "support": "Figure 2 caption states 'obtained from the peak width using xi = 2/FWHM'."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 113,
          "line_end": 113,
          "support": "Figure 2 caption: 'Correlation length of CDW order (grey circles) as a function of temperature, obtained from the peak width using xi = 2/FWHM.'"
        }
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "lsco_composition",
      "statement": "The sample is La1.885Sr0.115CuO4 (LSCO), a composition with well-established stripe-like CDW correlations.",
      "anchors": [
        {
          "line_start": 89,
          "line_end": 89,
          "support": "The paper states 'La1.885Sr0.115CuO4 (LSCO), a composition with well-established stripe-like CDW correlations'."
        }
      ]
    },
    {
      "condition_id": "rsxs_cu_l3_edge",
      "statement": "Measurements were performed using resonant soft x-ray scattering (RSXS) at the Cu L3-edge.",
      "anchors": [
        {
          "line_start": 89,
          "line_end": 89,
          "support": "The paper states 'high-statistics resonant soft x-ray scattering (RSXS) at Cu L3-edge'."
        }
      ]
    },
    {
      "condition_id": "tc_27k",
      "statement": "The superconducting transition temperature Tc is 27 K for the pristine LSCO crystal.",
      "anchors": [
        {
          "line_start": 82,
          "line_end": 82,
          "support": "Figure 1 caption: 'measured at Tc = 27 K'."
        }
      ]
    }
  ],
  "controls": [
    {
      "name": "temperature",
      "definition": "The sample temperature at which the CDW momentum profile is measured.",
      "unit": "K",
      "domain_kind": "numeric_values",
      "minimum": null,
      "maximum": null,
      "allowed_values": [
        12.4,
        27.0
      ],
      "domain_statement": "Two temperatures are explicitly reported: 27 K (just above Tc) and 12.4 K (deep in the superconducting state).",
      "anchors": [
        {
          "line_start": 95,
          "line_end": 97,
          "support": "The paper compares momentum profiles at 27 K and 12.4 K, reporting FWHM values at these temperatures."
        }
      ]
    }
  ],
  "readouts": [
    {
      "name": "fwhm",
      "definition": "Full width at half maximum of the CDW peak along the h-direction, measured in reciprocal lattice units (r.l.u.).",
      "unit": "r.l.u.",
      "statistic": "Reported as mean values with uncertainties from fits; the paper states '0.023 ± 0.0005' and '0.018 ± 0.0005' r.l.u. for the two temperatures.",
      "uncertainty": "The uncertainties are given as ±0.0005 r.l.u. for both values; the convention (e.g., standard deviation, standard error) is not specified in the text.",
      "resolution": null,
      "anchors": [
        {
          "line_start": 95,
          "line_end": 97,
          "support": "The paper reports FWHM values: 'from 0.023 ± 0.0005 to 0.018 ± 0.0005 r.l.u.'."
        }
      ]
    },
    {
      "name": "correlation_length",
      "definition": "Real-space correlation length of CDW order, obtained from the FWHM using xi = 2/FWHM.",
      "unit": "Angstrom",
      "statistic": "Reported as a mean value with uncertainty at Tc: '57.4 ± 0.5 Å'.",
      "uncertainty": "The uncertainty is given as ±0.5 Å; the convention is not specified.",
      "resolution": null,
      "anchors": [
        {
          "line_start": 103,
          "line_end": 103,
          "support": "The paper states 'At Tc, xi ≈ 57.4 ± 0.5 Å'."
        }
      ]
    }
  ],
  "claims": [
    {
      "claim_id": "fwhm_reduction_below_tc",
      "statement": "The CDW peak FWHM decreases from 0.023 ± 0.0005 r.l.u. at 27 K to 0.018 ± 0.0005 r.l.u. at 12.4 K, a 21% reduction that exceeds instrumental resolution.",
      "quantitative_form": "FWHM(12.4 K) = 0.018 r.l.u., FWHM(27 K) = 0.023 r.l.u.",
      "oracle_outputs": {
        "fwhm": {
          "op": "add",
          "args": [
            {
              "op": "multiply",
              "args": [
                {
                  "param": "fwhm_27k"
                },
                {
                  "op": "subtract",
                  "args": [
                    {
                      "var": "temperature"
                    },
                    {
                      "param": "temperature_27k"
                    }
                  ]
                }
              ]
            },
            {
              "param": "fwhm_27k"
            }
          ]
        }
      },
      "mechanism_ids": [
        "cdw_width_decomposition"
      ],
      "control_names": [
        "temperature"
      ],
      "control_domains": [
        {
          "control_name": "temperature",
          "domain_kind": "numeric_values",
          "minimum": null,
          "maximum": null,
          "allowed_values": [
            12.4,
            27.0
          ],
          "domain_statement": "The claim applies to the two reported temperatures: 27 K and 12.4 K.",
          "anchors": [
            {
              "line_start": 95,
              "line_end": 97,
              "support": "The paper reports FWHM values at these two temperatures."
            }
          ]
        }
      ],
      "readout_names": [
        "fwhm"
      ],
      "fixed_condition_ids": [
        "lsco_composition",
        "rsxs_cu_l3_edge",
        "tc_27k"
      ],
      "applicability": "The claim applies to the pristine LSCO crystal measured by RSXS at Cu L3-edge, at the two reported temperatures.",
      "statistical_basis": "The FWHM values are reported as mean ± 0.0005 r.l.u.; the paper states the reduction is statistically significant and robust to variations in background modeling, line shape fitting, and measurement geometry.",
      "uncertainty": "The uncertainty on each FWHM is ±0.0005 r.l.u.; the convention is not specified.",
      "depends_on": [],
      "anchors": [
        {
          "line_start": 95,
          "line_end": 97,
          "support": "The paper states the FWHM reduction from 0.023 ± 0.0005 to 0.018 ± 0.0005 r.l.u., a 21% reduction."
        }
      ]
    },
    {
      "claim_id": "correlation_length_at_tc",
      "statement": "At Tc, the CDW correlation length is approximately 57.4 ± 0.5 Å, corresponding to about 15 a-axis unit cells.",
      "quantitative_form": "xi(Tc) = 57.4 Å",
      "oracle_outputs": {
        "correlation_length": {
          "op": "divide",
          "args": [
            {
              "param": "fwhm_to_xi_factor"
            },
            {
              "var": "fwhm"
            }
          ]
        }
      },
      "mechanism_ids": [
        "correlation_length_conversion"
      ],
      "control_names": [
        "temperature"
      ],
      "control_domains": [
        {
          "control_name": "temperature",
          "domain_kind": "fixed_value",
          "minimum": null,
          "maximum": null,
          "allowed_values": [
            27.0
          ],
          "domain_statement": "The claim is specifically for the temperature at Tc, which is 27 K.",
          "anchors": [
            {
              "line_start": 103,
              "line_end": 103,
              "support": "The paper states 'At Tc, xi ≈ 57.4 ± 0.5 Å'."
            }
          ]
        }
      ],
      "readout_names": [
        "correlation_length"
      ],
      "fixed_condition_ids": [
        "lsco_composition",
        "rsxs_cu_l3_edge",
        "tc_27k"
      ],
      "applicability": "The claim applies to the pristine LSCO crystal at Tc = 27 K.",
      "statistical_basis": "The correlation length is reported as a mean value with uncertainty ±0.5 Å; the paper does not specify the number of measurements or the aggregation method.",
      "uncertainty": "The uncertainty is ±0.5 Å; the convention is not specified.",
      "depends_on": [
        "fwhm_reduction_below_tc"
      ],
      "anchors": [
        {
          "line_start": 103,
          "line_end": 103,
          "support": "The paper states 'At Tc, xi ≈ 57.4 ± 0.5 Å, corresponding to ~15 a-axis unit cells.'"
        }
      ]
    }
  ],
  "source_ambiguities": [
    {
      "ambiguity_id": "bcs_fit_parameters_not_reported",
      "statement": "The paper mentions a BCS-like gap function fit to the phase coherence enhancement (Fig. 2c) but does not report the fit parameters (e.g., gap amplitude, exponent) in the text.",
